style.css:
/* Default: Normal Difficulty Face */
img {
  content: url('https://static.wikia.nocookie.net/geometry-dash-fan-ideas/images/f/fb/Normal.png/revision/latest?cb=20240919112530');
  width: 100px;
  height: auto;
  display: inline-block;
  border: 2px solid #00ccff;
  border-radius: 10px;
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}

/* 10% chance: Alternate Image using nth-of-type */
img:nth-of-type(10n) {
  content: url('https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTEVnLLYXO8xYEK4mUxEjaZDk6ofypNy2vTdQ&s');
  border-color: #ff0000;
}

/* Hover Effect */
img:hover {
  transform: scale(1.1);
  box-shadow: 0 8px 16px rgba(0, 0, 0, 0.3);
}
